def _tracer_decor(c, x0, y0):
    """Pose le dessin de la maquette dans le carton (x0, y0 = coin bas-gauche)."""
    def X(v):
        return x0 + v / 1000.0 * CARD_W

    def Y(v):
        return y0 + CARD_H - v / 1000.0 * CARD_H

    for groupe in _DECOR.split("#"):
        p = c.beginPath()
        for contour in groupe.split("|"):
            i = 0
            while i < len(contour):
                op = contour[i]
                i += 1
                j = i
                while j < len(contour) and contour[j] not in "mlc":
                    j += 1
                v = [float(t) for t in contour[i:j].split(",")]
                i = j
                if op == "m":
                    p.moveTo(X(v[0]), Y(v[1]))
                elif op == "l":
                    p.lineTo(X(v[0]), Y(v[1]))
                else:
                    p.curveTo(X(v[0]), Y(v[1]), X(v[2]), Y(v[3]), X(v[4]), Y(v[5]))
            p.close()
        c.drawPath(p, stroke=0, fill=1, fillMode=FILL_EVEN_ODD)
    for (a, b, d, e), lw in ((CADRE_EXT, 1.2), (CADRE_INT, 0.9)):
        c.setLineWidth(lw)
        c.rect(X(a), Y(e), X(d) - X(a), Y(b) - Y(e), stroke=1, fill=0)
    c.setLineWidth(0.9)
    c.line(X(SEPARATEUR[0]), Y(SEPARATEUR[1]), X(SEPARATEUR[0]), Y(SEPARATEUR[2]))


def _forme_decor(c, couleur_hex):
    """Le dessin de la maquette est lourd (un millier de courbes) : on ne le
    grave qu'UNE FOIS par couleur dans le PDF, puis chaque carton s'y
    réfère. Sans ça une rame de 500 feuilles pèserait 180 Mo."""
    nom = "MQ90_" + couleur_hex.lstrip("#")
    faites = getattr(c, "_mq90_formes", None)
    if faites is None:
        faites = set(); c._mq90_formes = faites
    if nom not in faites:
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        col = colors.HexColor(couleur_hex)
        c.setFillColor(col); c.setStrokeColor(col)
        _tracer_decor(c, 0, 0)
        c.endForm()
        faites.add(nom)
    return nom


def _gen_carte(rng):
    """10 pairs distincts entre 2 et 90, en 2 colonnes de 5 croissantes."""
    tirage = sorted(rng.sample(PAIRS, NB_NUMEROS))
    return tirage[0::2], tirage[1::2]


def _dessiner_carte(c, x0, y0, gauche, droite, couleur_hex, serie,
                    style="eco", nom_pied="", telephone="", evenement_id=""):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)

    # 1) LE DESSIN DE MAEVA, tel quel (gravé une fois, reposé ici)
    c.saveState()
    c.translate(x0, y0)
    c.doForm(_forme_decor(c, couleur_hex))
    c.restoreState()

    # 2) LES CHIFFRES DANS LES BULLES — la seule chose qu'on ajoute
    for k, (bx, by, _br) in enumerate(BULLES):
        val = gauche[k // 2] if k % 2 == 0 else droite[k // 2]
        cx = x0 + bx / 1000.0 * CARD_W
        cy = y0 + CARD_H - by / 1000.0 * CARD_H
        if _sec:
            _sec.chiffre_micro(c, val, cx, cy - _T_NUM * 0.36, _T_NUM, gris_ch, police_ch)
        else:
            c.setFillColor(gris_ch); c.setFont(police_ch, _T_NUM)
            c.drawCentredString(cx, cy - _T_NUM * 0.36, str(val))

    # 3) LE NOM DE L'ENSEIGNE dans le bandeau du bas de la maquette
    nom = (str(nom_pied).replace("|", " ").strip() or "2Kea&Associ\u00e9")
    if telephone:
        nom += "  " + str(telephone).strip()
    libre = PIED_LARG / 1000.0 * CARD_W
    t_nom = 7.5
    while t_nom > 3.6 and pdfmetrics.stringWidth(nom, "Helvetica", t_nom) > libre:
        t_nom -= 0.2
    c.setFillColor(colors.black); c.setFont("Helvetica", t_nom)
    c.drawCentredString(x0 + CARD_W / 2, y0 + CARD_H - PIED_Y / 1000.0 * CARD_H, nom)

    # 4) LE N° DE SÉRIE, discret, dans le couloir sous le carton
    c.setFillColor(GRIS); c.setFont(POLICE, 3.6)
    c.drawRightString(x0 + CARD_W, y0 - 2.0 * mm, "N\u00b0 %06d" % serie)

    if _sec and evenement_id:
        try:
            _sec.carton_qr(c, x0 + 1.5 * mm, y0 - 2.6 * mm, 0, evenement_id, serie)
        except Exception:
            pass


def generer_pdf(nb_cartes=12, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="", telephone="",
                style="eco", evenement_id="", page_start=1):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    # ⚠️ GRAINE : deux lots lancés avec le même serie_start sortent
    #    identiques. Pour un second tirage, décaler serie_start.
    rng = random.Random(290000 + int(serie_start))
    serie = int(serie_start)
    faites = 0
    no_page = max(1, int(page_start))

    # ⚠️ on grave les dessins AVANT d'ouvrir la première page
    if couleur:
        teintes = [couleur_perso.strip()] if couleur_perso.strip() else list(RAINBOW)
    else:
        teintes = ["#000000"]
    for t in teintes:
        _forme_decor(c, t)

    for _ in range(nb_pages):
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 6)
        c.drawCentredString(PAGE_W / 2, PAGE_H - 4.2 * mm, "%d" % no_page)

        for slot in range(CARTES_PAGE):
            if faites >= nb_cartes:
                break
            ci = slot % COLS_PAGE
            ri = slot // COLS_PAGE
            x0 = MARGIN_X + ci * (CARD_W + GUTTER_X)
            y0 = PAGE_H - MARGIN_TOP - (ri + 1) * CARD_H - ri * GUTTER_Y

            if couleur:
                coul = couleur_perso.strip() if couleur_perso.strip() else RAINBOW[faites % len(RAINBOW)]
            else:
                coul = "#000000"

            g, d = _gen_carte(rng)
            _dessiner_carte(c, x0, y0, g, d, coul, serie, style=style,
                            nom_pied=nom_evenement, telephone=telephone,
                            evenement_id=evenement_id)
            serie += 1
            faites += 1

        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    # ⚠️⚠️ ON RENVOIE LE TAMPON, PAS LES OCTETS (leçon du 22/09).
    #    Toute la plateforme fait .read() sur ce que rend un
    #    générateur — l'email, la vignette, le découpage des grosses
    #    commandes. Un « return buf.read() » renvoie des octets, qui
    #    n'ont pas de .read() : la fabrication plantait et le jeu
    #    semblait cassé. TOUS les générateurs de la maison rendent buf.
    return buf
